// Tier 1: original DOS struct layout, as documented in the decompiled headers.
// Cases are generated by tools/gen_layout_tests.py; regenerate after editing engine/Basic.h.
#include <gtest/gtest.h>

#include <cstddef>

#include "sub_main.h"
#include "engine/Basic.h"

#if defined(_MSC_VER)
#pragma warning(disable : 4996)
#endif

#define LAYOUT_SIZE(T, N) \
	TEST(Layout, T##_size) { EXPECT_EQ(sizeof(T), (size_t)(N)) << #T " must keep its DOS size"; }
#define LAYOUT_OFFSET(T, F, N) \
	TEST(Layout, T##_##F) { EXPECT_EQ(offsetof(T, F), (size_t)(N)) << #T "::" #F; }

#include "generated/layout_cases.inc"

// Facts not expressible through comments.
TEST(Layout, GameStateStructOffsets)
{
	// Type_str_AE400_AE3F0 (the 232713-byte block at DS:AE400) - field names carry DOS offsets.
	using T = Type_str_AE400_AE3F0;
	EXPECT_EQ(offsetof(T, rand_4), 4u);
	EXPECT_EQ(offsetof(T, var_u16_8), 8u);
	EXPECT_EQ(offsetof(T, str_12), 12u);
	EXPECT_EQ(offsetof(T, var_u32_32), 32u);
	EXPECT_EQ(offsetof(T, var_u32_576), 576u);
	EXPECT_EQ(offsetof(T, var_u32_593), 593u);
	EXPECT_EQ(offsetof(T, var_u32_4593), 4593u);
	EXPECT_EQ(offsetof(T, var_u32_4597), 4597u);
	EXPECT_EQ(offsetof(T, str_9177), 9177u);
	EXPECT_EQ(offsetof(T, str_13323), 13323u);
	EXPECT_EQ(offsetof(T, var_29715), 29715u);
	EXPECT_EQ(offsetof(T, str_29795), 29795u);
	EXPECT_EQ(offsetof(T, str_193795), 193795u);
	EXPECT_EQ(offsetof(T, str_232607), 232607u);
	EXPECT_EQ(sizeof(T), 232713u);
}

TEST(Layout, Type160KnownOffsets)
{
	// Offsets used as raw *(T*)(p + off) in the decompiled code, cross-checked with named access.
	EXPECT_EQ(sizeof(Type_160), 946u);
	EXPECT_EQ(offsetof(Type_160, v_46), 46u);
	EXPECT_EQ(offsetof(Type_160, var_48), 48u);
	EXPECT_EQ(offsetof(Type_160, var_50), 50u);
	EXPECT_EQ(offsetof(Type_160, var_52), 52u);
	EXPECT_EQ(offsetof(Type_160, u32_308), 308u);
	EXPECT_EQ(offsetof(Type_160, u16_327), 327u);
	EXPECT_EQ(offsetof(Type_160, u16_329), 329u);
}

TEST(Layout, EntityArrayIs1000x164)
{
	EXPECT_EQ(sizeof(((Type_str_AE400_AE3F0*)nullptr)->str_29795), 164000u);
}

TEST(Layout, TypeTabRecordIs6Bytes)
{
	// .TAB files are arrays of 6-byte records {uint32 offset; uint8 w; uint8 h} relocated in place.
	EXPECT_EQ(sizeof(TypeTab), 6u);
}
